import { MEDICAMENTOS_PROTOCOLO_RENAME } from './medicamentosRenameJson';

export const TODOS_MEDICAMENTOS_BRASIL: MedicamentoPrescricao[] = [
  ...MEDICAMENTOS_BRASIL,
  ...MEDICAMENTOS_PROTOCOLO_RENAME
];

export function buscarMedicamentosBrasil(termo: string): MedicamentoPrescricao[] {
  if (!termo || termo.trim().length === 0) {
    return MEDICAMENTOS_BRASIL.slice(0, 20);
  }
  const clean = termo.toLowerCase().trim();
  // Regra 1: No campo de busca de medicamentos, filtre pelo label ou categoria conforme o médico digita.
  return TODOS_MEDICAMENTOS_BRASIL.filter((m) =>
    m.label.toLowerCase().includes(clean) ||
    m.categoria.toLowerCase().includes(clean) ||
    m.medicamento.toLowerCase().includes(clean)
  );
}

